"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[535],{2206:e=>{e.exports=JSON.parse('{"functions":[{"name":"linear","desc":"Straight segments between the points. Needs at least two points to make a segment.","params":[{"name":"points","desc":"Relative to the pivot.","lua_type":"{VectorLike}?"},{"name":"pivot","desc":"Defaults to the origin.","lua_type":"VectorLike?"}],"returns":[{"desc":"","lua_type":"LinearSpline"}],"function_type":"static","source":{"line":90,"path":"src/init.luau"}},{"name":"bezier","desc":"Cubic Bezier curves: points 1-4 make the first curve, 4-7 the second, and so on, so it passes through every\\nthird point. Points past the last complete curve are kept but ignored.","params":[{"name":"points","desc":"Relative to the pivot.","lua_type":"{VectorLike}?"},{"name":"pivot","desc":"Defaults to the origin.","lua_type":"VectorLike?"}],"returns":[{"desc":"","lua_type":"CubicSpline"}],"function_type":"static","source":{"line":103,"path":"src/init.luau"}},{"name":"hermite","desc":"Passes through every point, leaving each one with its velocity. Change velocities with\\n[CubicSpline:setVelocity].","params":[{"name":"points","desc":"Relative to the pivot.","lua_type":"{VectorLike}?"},{"name":"velocities","desc":"One per point. Missing ones are zero.","lua_type":"{VectorLike}?"},{"name":"pivot","desc":"Defaults to the origin.","lua_type":"VectorLike?"}],"returns":[{"desc":"","lua_type":"CubicSpline"}],"function_type":"static","source":{"line":117,"path":"src/init.luau"}},{"name":"cardinal","desc":"Passes through every point, with velocities of `(next - previous) * scale`. The end points mirror their only\\nneighbour. Change the scale with [CubicSpline:setScale].","params":[{"name":"points","desc":"Relative to the pivot.","lua_type":"{VectorLike}?"},{"name":"scale","desc":"How strongly the curve follows its neighbours; 0.5 is Catmull-Rom.","lua_type":"number"},{"name":"pivot","desc":"Defaults to the origin.","lua_type":"VectorLike?"}],"returns":[{"desc":"","lua_type":"CubicSpline"}],"function_type":"static","source":{"line":131,"path":"src/init.luau"}},{"name":"catmullRom","desc":"A [Splynx.cardinal] spline with a scale of 0.5: passes through every point with natural-looking curves.","params":[{"name":"points","desc":"Relative to the pivot.","lua_type":"{VectorLike}?"},{"name":"pivot","desc":"Defaults to the origin.","lua_type":"VectorLike?"}],"returns":[{"desc":"","lua_type":"CubicSpline"}],"function_type":"static","source":{"line":143,"path":"src/init.luau"}},{"name":"bSpline","desc":"A uniform cubic B-spline: smooth everywhere, including across joints, but it only passes near its points.\\nNeeds at least four points.","params":[{"name":"points","desc":"Relative to the pivot.","lua_type":"{VectorLike}?"},{"name":"pivot","desc":"Defaults to the origin.","lua_type":"VectorLike?"}],"returns":[{"desc":"","lua_type":"CubicSpline"}],"function_type":"static","source":{"line":156,"path":"src/init.luau"}},{"name":"sampled","desc":"A static copy of `source` as straight segments `spacing` studs apart along it, for the fastest distance\\nlookups. Smaller spacing follows curves more closely. It doesn\'t follow later edits to `source`; sample it\\nagain after changing it.","params":[{"name":"source","desc":"The spline to copy.","lua_type":"LinearSpline | CubicSpline"},{"name":"spacing","desc":"Studs between samples, along the spline.","lua_type":"number"}],"returns":[{"desc":"","lua_type":"SampledSpline"}],"function_type":"static","errors":[{"lua_type":"\\"Spacing must be more than 0\\"","desc":"If `spacing` isn\'t positive."},{"lua_type":"\\"Spline doesn\'t have enough points to make a curve\\"","desc":"If `source` has no curves."}],"source":{"line":172,"path":"src/init.luau"}}],"properties":[],"types":[{"name":"VectorLike","desc":"Anything Splynx accepts as a position or velocity.","lua_type":"Vector3 | vector","source":{"line":68,"path":"src/init.luau"}},{"name":"Spline","desc":"Any spline.","lua_type":"LinearSpline | CubicSpline | SampledSpline","source":{"line":78,"path":"src/init.luau"}}],"name":"Splynx","desc":"Splines built for fast lookups. There are three kinds:\\n\\n| Kind | Made by | Shape | Editable |\\n| --- | --- | --- | --- |\\n| [LinearSpline] | [Splynx.linear] | Straight segments between the points | Yes |\\n| [CubicSpline] | [Splynx.bezier], [Splynx.hermite], [Splynx.cardinal], [Splynx.catmullRom], [Splynx.bSpline] | Smooth curves | Yes |\\n| [SampledSpline] | [Splynx.sampled] | Straight segments a fixed distance apart along another spline | No |\\n\\nLookups are prioritised over edits: everything that speeds up a lookup is precomputed, and rebuilt when the\\nspline changes. Run `lune run bench` for current numbers.\\n\\n### Points and the pivot\\n\\nPoints are relative to the spline\'s pivot, and every position a spline returns has the pivot applied. Moving\\nthe pivot moves the whole spline without rebuilding anything.\\n\\n### Alpha and distance\\n\\n`getPos(alpha)` splits alpha evenly across a spline\'s curves, so it speeds up and slows down along curves of\\ndifferent lengths. For a constant speed, work in distances: `getPosAtDistance`, `getUniformPos` and\\n`sampleUniform`.\\n\\n### Hints\\n\\nDistance lookups take an optional hint and return a new one. Passing back the previous call\'s hint starts the\\nnext lookup where the last one ended, which makes lookups for something moving along the spline cheaper. Any\\nhint gives the same result, so a stale one is fine; leave it out for lookups that jump around.\\n\\n```lua\\nlocal spline = Splynx.catmullRom({ Vector3.new(0, 0, 0), Vector3.new(10, 5, 0), Vector3.new(20, 0, 0) })\\n\\nlocal distance, hint = 0, nil\\nRunService.Heartbeat:Connect(function(deltaTime)\\n    distance = (distance + 12 * deltaTime) % spline:getLength()\\n    local position\\n    position, hint = spline:getPosAtDistance(distance, hint)\\n    part.Position = position\\nend)\\n```\\n\\n### Vectors\\n\\nInputs accept `Vector3` or `vector`, and outputs are `vector`. On Roblox the two are the same value, but the\\ntype checker treats them as different types, so outputs may need a cast where a `Vector3` is expected.","source":{"line":52,"path":"src/init.luau"}}')}}]);